function TrailStageEnterNode:RefreshUI()
    local trialRemainTime = checkInt(playerComponent.playerDojo.trialRemainTime)
    if trialRemainTime <= Constants.MIN_TRIAL_CAN_ENTER then
        self.TxtNextStart.text = localize("结算中")
    else
        local second = trialRemainTime - Constants.MIN_TRIAL_CAN_ENTER
        local text = localize('本期比赛结束还剩余:_time_', {_time_ = GetTimeHMS(second, 22) })
        self.TxtNextStart.text = text

        --先清除一下之前的缓存
        self:Clear()
        self._timer = CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count <= 0 then
                self:RefreshUI()
            else
                self.TxtNextStart.text = localize('本期比赛结束还剩余:_time_', {_time_ = GetTimeHMS(count, 22) })
            end
        end, second, false, true, true)
    end
end

function TrailStageEnterNode:Clear()
    if not isNull(self._timer) then
        ---删除计时器
        CDTimerModule.GetInstance():RemoveCD(self._timer)
        self._timer = nil
    end
end

--委托成功后回调刷新界面
function TrailStageEnterNode:OnRefreshTrailStage(body)
    self:RefreshUI()
end

