function TrailStageEnterNode:OnClickBtnAction()
    local trialRemainTime = checkInt(playerComponent.playerDojo.trialRemainTime)
    if trialRemainTime <= Constants.MIN_TRIAL_CAN_ENTER then
        GameUtils.Toast(localize('试炼未开始'))
        return
    end
    UIModule.OpenDialog({ id = Constants.UITypeIds.UITrailStageHome }, { { id = Constants.UITypeIds.BattleSelection } })
end

